-- The unpaged supply query, kept only as a bounded-test reference and a negative cost control.
WITH fixed AS(SELECT * FROM unnest($1::bytea[],$2::bytea[]) f(policy,name)) SELECT encode(f.policy,'hex')||encode(f.name,'hex'),trunc(coalesce(sum(a.quantity) FILTER(WHERE o.id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.tx_in i WHERE i.tx_out_id=o.tx_id AND i.tx_out_index=o.index AND i.id BETWEEN 0 AND $3::bigint*16777216+16777215)),0))::text FROM fixed f LEFT JOIN public.multi_asset m ON m.policy=f.policy AND m.name=f.name LEFT JOIN public.ma_tx_out a ON a.ident=m.id AND a.id BETWEEN 0 AND $3::bigint*68719476736+68719476735 LEFT JOIN public.tx_out o ON o.id=a.tx_out_id AND o.id BETWEEN 0 AND $3::bigint*16777216+16777215 GROUP BY f.policy,f.name ORDER BY f.policy,f.name
